        ["EsRecharge"]=("восстановление {0} в секунду; старт через {1} с без урона по Щиту (без модели прерывания)","recharge {0}/s; starts after {1}s without ES damage (no interruption state)"),
        ["ReservationNote"]=("зарезервировано {0} из {1} ({2}%). Использован explicit resolved context.","reserved {0} of {1} ({2}%). Explicit resolved context supplied."),
        ["ArmourEstimate"]=("≈ −{0}% урона от удара монстра {1} ур. (A/(A+12·урон))","≈ −{0}% from a level-{1} monster hit (A/(A+12·dmg))"),
        ["EvasionNote"]=("рейтинг; шансы показаны против стандартного монстра уровня персонажа","rating; chances are shown against a same-level default monster"),
